// transkrip teks (pola chatGemini) sejak titik contextStart ("Sesi baru").
//
// Bentuk API meniru lib/perplexity.js persis supaya klien jendela AI bisa
// memakai kode yang sama untuk dua provider.

const https = require('https')
const crypto = require('crypto')
const fsp = require('fs/promises')
const os = require('os')
const path = require('path')
const { sendJson, readJson } = MOD_HTTP

const HISTORY_FILE = path.join(DATA_DIR, 'gemini-history.json')
const MAX_KEEP = 200
const MAX_TEXT = 4000

// ---------- riwayat ----------
let histCache = null
let saveChain = Promise.resolve()

async function loadHistory() {
  if (histCache) return histCache
  try {
    histCache = JSON.parse(await fsp.readFile(HISTORY_FILE, 'utf8'))
  } catch {
    histCache = { messages: [], contextStart: 0 }
  }
  if (!histCache || !Array.isArray(histCache.messages)) histCache = { messages: [], contextStart: 0 }
  if (typeof histCache.contextStart !== 'number') histCache.contextStart = 0
  return histCache
}

function saveHistory() {
  const data = JSON.stringify(histCache)
  saveChain = saveChain
    .then(() => fsp.writeFile(HISTORY_FILE + '.tmp', data))
    .then(() => fsp.rename(HISTORY_FILE + '.tmp', HISTORY_FILE))
    .catch(() => {})
  return saveChain
}

function pushMsg(hist, from, text) {
  const lastId = hist.messages.length ? hist.messages[hist.messages.length - 1].id : 0
  const msg = { id: lastId + 1, from, text, ts: Date.now() }
  hist.messages.push(msg)
  if (hist.messages.length > MAX_KEEP) {
    const cut = hist.messages.length - MAX_KEEP
    hist.messages = hist.messages.slice(-MAX_KEEP)
    hist.contextStart = Math.max(0, hist.contextStart - cut)
  }
  return msg
}

function hasContext(hist) {
  return hist.messages.slice(hist.contextStart).some(m => m.from === 'user' || m.from === 'ai')
}

// ---------- klien Gemini web (mode tamu; kode pemilik, disesuaikan) ----------
const BASE_URL = 'https://gemini.google.com'
const UA = 'Mozilla/5.0 (Linux; Android 10; K) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/137.0.0.0 Mobile Safari/537.36'
const BL = 'boq_assistant-bard-web-server_20260705.15_p0'

function generateAtToken() {
  const random = crypto.randomBytes(16).toString('base64url').slice(0, 22)
  const ts = Date.now() * 1000
  return `AOOh${random}:${ts}`
}

function generateFSid() {
  return '-' + String(Math.floor(Math.random() * 1000000000) + 1000000000)
}

function generateTokenBlob() {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_'
  const random = (n) => Array.from({ length: n }, () => chars[Math.floor(Math.random() * chars.length)]).join('')
  return '!' + random(24) + 'NAAa-PB6hnjxC' + random(18) + 'AEABE' + random(12) +
    'Z1IzrYRasYCYYnM4bZXAlvfpPcJe2g2Ye8XDL3Ck5BCikk5IYm5xZrnIsIkA0SEgfgSLBh-eSq-mq5McSAgAA' +
    random(8) + 'SAAAC' + random(8) + 'BB34ARK' + random(1100)
}

class GeminiClient {
  constructor(opts = {}) {
    this.atToken = generateAtToken()
    this.fSid = generateFSid()
    this.tokenBlob = generateTokenBlob()
    this.deviceId = crypto.randomUUID()
    this.hl = opts.hl || 'id'
    this._reqid = Math.floor(Math.random() * 10000000)
    this._sessionId = crypto.randomBytes(16).toString('hex')
    this._conversationId = null
    this._responseId = null
  }

  _headers(extra = {}) {
    const h = {
      authority: 'gemini.google.com',
      accept: '*/*',
      'accept-language': 'id-ID,id;q=0.9,en-US;q=0.8,en;q=0.7',
      'content-type': 'application/x-www-form-urlencoded;charset=UTF-8',
      origin: BASE_URL,
      referer: BASE_URL + '/',
      'sec-ch-ua': '"Chromium";v="137", "Not/A)Brand";v="24"',
      'sec-ch-ua-mobile': '?1',
      'sec-ch-ua-platform': '"Android"',
      'user-agent': UA,
      'x-same-domain': '1',
      'x-goog-ext-525001261-jspb': `[1,null,null,null,"fbb127bbb056c959",null,null,0,[4],null,null,1,null,null,1,null,"${this.deviceId}"]`,
      'x-goog-ext-525005358-jspb': `["${this.deviceId}",1]`,
      'x-goog-ext-73010989-jspb': '[0]',
      'x-goog-ext-73010990-jspb': '[0,0,0]'
    }
    return Object.assign(h, extra)
  }

  _buildPayload(message) {
    const inner = [
      [message, 0, null, null, null, null, 0],
      ['id'],
      ['', '', '', null, null, null, null, null, null, ''],
      this.tokenBlob,
      this._sessionId,
      null,
      [0],
      1,
      null, null, 1, 0,
      null, null, null, null, null,
      [[0]],
      0,
      null, null, null, null, null, null, null, null,
      1,
      null, null,
      [4],
      null, null, null, null, null, null, null, null, null, null,
      [2],
      null, null, null, null, null, null, null, null, null, null, null,
      0,
      null, null, null, null, null,
      this.deviceId,
      null,
      [],
      null, null, null, null, null, null,
      1,
      null, null, null, null, null, null, null, null, null, null,
      1
    ]
    const outer = [null, JSON.stringify(inner)]
    const params = new URLSearchParams()
    params.append('f.req', JSON.stringify(outer))
    params.append('at', this.atToken)
    return params.toString()
  }

  _parseStream(res) {
    return new Promise((resolve, reject) => {
      let buf = ''
      let fullText = ''
      res.on('data', chunk => {
        buf += chunk.toString('utf8')
        const lines = buf.split('\n')
        buf = lines.pop()
        for (const line of lines) {
          let cleaned = line
          if (cleaned.startsWith(")]}'")) cleaned = cleaned.slice(4)
          if (/^\d+$/.test(cleaned.trim())) continue
          if (!cleaned.trim()) continue
          let parsed
          try { parsed = JSON.parse(cleaned) } catch { continue }
          if (!Array.isArray(parsed) || !parsed[0]) continue
          const encoded = parsed[0]?.[2]
          if (!encoded) continue
          let inner
          try { inner = JSON.parse(encoded) } catch { continue }
          const messages = inner[4]
          if (Array.isArray(messages)) {
            for (const block of messages) {
              if (!Array.isArray(block)) continue
              const textArr = block[1]
              if (Array.isArray(textArr) && textArr.length > 0 && typeof textArr[0] === 'string') {
                if (textArr[0].length >= fullText.length) fullText = textArr[0]
              }
            }
          }
        }
      })
      res.on('end', () => resolve(fullText))
      res.on('error', err => reject(new Error('Stream Gemini putus: ' + err.message)))
    })
  }

  async sendMessage(message) {
    this._reqid++
    const payload = this._buildPayload(message)
    const url = new URL(BASE_URL + '/_/BardChatUi/data/assistant.lamda.BardFrontendService/StreamGenerate')
    url.searchParams.set('bl', BL)
    url.searchParams.set('f.sid', this.fSid)
    url.searchParams.set('hl', this.hl)
    url.searchParams.set('_reqid', String(this._reqid))
    url.searchParams.set('rt', 'c')
    return new Promise((resolve, reject) => {
      const req = https.request({
        hostname: url.hostname,
        path: url.pathname + url.search,
        method: 'POST',
        headers: this._headers({ 'content-length': String(Buffer.byteLength(payload)) }),
        timeout: 120000
      }, async res => {
        if (res.statusCode >= 400) {
          let errData = ''
          res.on('data', c => { errData += c })
          res.on('end', () => reject(new Error('Gemini web HTTP ' + res.statusCode + ': ' + errData.slice(0, 200))))
          return
        }
        try {
          resolve(await this._parseStream(res))
        } catch (e) { reject(e) }
      })
      req.on('error', err => reject(new Error('Gagal menghubungi Gemini: ' + err.message)))
      req.on('timeout', () => { req.destroy(); reject(new Error('Gemini timeout (120 detik).')) })
      req.write(payload)
      req.end()
    })
  }
}

async function askGemini(text, hist) {
  const prior = hist.messages
    .slice(hist.contextStart)
    .filter(m => m.from === 'user' || m.from === 'ai')
  let fullPrompt = ''
  if (prior.length) {
    fullPrompt = prior.map(m => (m.from === 'user' ? 'User: ' : 'Assistant: ') + m.text).join('\n\n') + '\n\n'
  }
  fullPrompt += 'User: ' + text + '\n\nAssistant:'
  const client = new GeminiClient({ hl: 'id' })
  const answer = await client.sendMessage(fullPrompt.trim())
  if (!answer) throw new Error('Jawaban Gemini kosong — akses tamu mungkin sedang dibatasi Google, coba lagi nanti.')
  return answer
}

// ---------- API ----------
let asking = false

async function handleApi(req, res, url, route) {
  if (route === 'GET /api/gemini/status') {
    const hist = await loadHistory()
    sendJson(res, 200, {
      registered: true,
      guest: true,
      email: null,
      hasSession: hasContext(hist)
    })
    return
  }

  if (route === 'GET /api/gemini/list') {
    const hist = await loadHistory()
    sendJson(res, 200, { messages: hist.messages, hasSession: hasContext(hist) })
    return
  }

  if (route === 'POST /api/gemini/new') {
    const hist = await loadHistory()
    const msg = pushMsg(hist, 'sys', 'Sesi baru dimulai')
    hist.contextStart = hist.messages.length
    await saveHistory()
    sendJson(res, 200, { ok: true, message: msg, hasSession: false })
    return
  }

  if (route === 'POST /api/gemini/delete') {
    const bodyIn = await readJson(req)
    const id = parseInt(bodyIn.id, 10) || 0
    const hist = await loadHistory()
    const idx = hist.messages.findIndex(m => m.id === id)
    if (idx >= 0) {
      hist.messages.splice(idx, 1)
      if (idx < hist.contextStart) hist.contextStart -= 1
      await saveHistory()
    }
    sendJson(res, 200, { ok: true })
    return
  }

  if (route === 'POST /api/gemini/clear') {
    const hist = await loadHistory()
    hist.messages = []
    hist.contextStart = 0
    await saveHistory()
    sendJson(res, 200, { ok: true, hasSession: false })
    return
  }

  if (route === 'POST /api/gemini/ask') {
    const bodyIn = await readJson(req)
    const text = String(bodyIn.text || '').trim()
    if (!text) throw new Error('Pertanyaan kosong.')
    if (text.length > MAX_TEXT) throw new Error('Pertanyaan terlalu panjang.')
    if (asking) throw new Error('Masih menjawab pertanyaan sebelumnya — tunggu sebentar.')
    asking = true
    try {
      const hist = await loadHistory()
      const answer = await askGemini(text, hist)
      const userMsg = pushMsg(hist, 'user', text)
      const aiMsg = pushMsg(hist, 'ai', answer)
      await saveHistory()
      sendJson(res, 200, { ok: true, user: userMsg, ai: aiMsg, hasSession: true })
    } finally {
      asking = false
    }
    return
  }

  sendJson(res, 404, { error: 'Tidak ditemukan.' })
}

async function handle(req, res, url, route) {
  if (!url.pathname.startsWith('/api/gemini/')) return false
  await handleApi(req, res, url, route)
  return true
}

return { handle }

