function sendJson(res, code, obj) {
  const body = JSON.stringify(obj)
  res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': Buffer.byteLength(body) })
  res.end(body)
}

function proxyImg(req, src) {
  if (!src) return ''
  // APK: proksi /web/go berjalan di port yang SAMA dengan aplikasi
  // (di Termux ia origin port+1 terpisah), jadi URL gambar cukup
  // relatif same-origin — pola yang sama dengan MOD_KOMIK di bundle.
  // Segmen terakhir adalah cfg.token APK ('local'), bukan token rahasia.
  const b = Buffer.from(src, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
  return '/web/go/' + b + '.n/' + encodeURIComponent(cfg.token || '')
}

