function isBlockedTagName(name) { return BLOCKED_SET.has(normalizeTagName(name)) }
function isBlockedTagId(id) { return BLOCKED_TAG_IDS.has(Number(id)) }
function galleryTagNames(g) {
  if (!g) return []
  if (Array.isArray(g.tags_all)) return g.tags_all.map(x => x && x.name).filter(Boolean)
  if (Array.isArray(g.tags)) return g.tags.map(x => x && x.name).filter(Boolean)
  return []
}
function galleryTagIds(g) {
  if (!g) return []
  if (Array.isArray(g.tag_ids)) return g.tag_ids.map(Number)
  if (Array.isArray(g.tags_all)) return g.tags_all.map(x => Number(x.id)).filter(Boolean)
  return []
}
