// Ambil JSON API v2 lewat scrapeFetch. scrapeFetch mengembalikan
// body apa adanya walau status bukan 200, jadi validasi bentuk
// JSON wajib di sini. Menerima objek {..} maupun array [..]
// (popular mengembalikan array langsung).
async function fetchApiRaw(apiPath) {
  let body = ''
  try {
    body = await wc.scrapeFetch(BASE + apiPath, BASE + '/')
  } catch (e) {
    throw new Error('Gagal menghubungi nhentai: ' + (e.message || String(e)))
  }
  const t = String(body || '').trim()
  if (!t.startsWith('{') && !t.startsWith('[')) {
    throw cloudflareError()
  }
  let j
  try { j = JSON.parse(t) } catch { throw cloudflareError() }
  if (j && j.error) throw new Error('nhentai: ' + String(j.error) + (j.details ? ' ' + JSON.stringify(j.details) : ''))
  return j
}
async function fetchApi(apiPath) {
  // P2a: backoff rate-limit — coba ulang sekali setelah 7 detik; bila
  // masih kena, lempar pesan yang jelas, bukan error mentah API.
  try { return await fetchApiRaw(apiPath) } catch (e) {
    if (!/rate limit/i.test(String((e && e.message) || e))) throw e
    await new Promise(r => setTimeout(r, 7000))
    try { return await fetchApiRaw(apiPath) } catch (e2) {
      if (/rate limit/i.test(String((e2 && e2.message) || e2))) throw new Error('nhentai: Batas kecepatan API tercapai — coba lagi beberapa detik.')
      throw e2
    }
  }
}

